import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Monitoring Ceph with Prometheus - Jan Fajerski, SUSE","description":"","frontmatter":{"title":"Monitoring Ceph with Prometheus - Jan Fajerski, SUSE","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Prometheus","Ceph","Monitoring","Storage","Distributed Systems"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Monitoring_Ceph_with_Prometheus_-_Jan_Fajerski_SUSE.md","filePath":"posts/2019/Monitoring_Ceph_with_Prometheus_-_Jan_Fajerski_SUSE.md","lastUpdated":1780459816000}'),s={name:"posts/2019/Monitoring_Ceph_with_Prometheus_-_Jan_Fajerski_SUSE.md"};function l(n,e,p,u,h,_){return r(),o("div",null,[...e[0]||(e[0]=[i("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： [请填写会议时间]</p><p><strong>参会人员</strong>： [请填写参会人员]</p><p><strong>会议主题</strong>： Prometheus监控工具介绍与Ceph应用</p><p><strong>会议内容</strong>：</p><ul><li><strong>Prometheus 简介</strong>： <ul><li>Prometheus由SoundCloud于2012年开发，是CNCF会员项目，适用于高维数值数据监控。</li><li>Prometheus基于拉取模式，从端点拉取指标，具有可扩展性。</li><li>Prometheus包含强大的查询语言PromQL，支持标签匹配、算术运算、聚合操作等。</li><li>Prometheus的关键组件包括Exporter（暴露指标的组件）和Alert Manager（处理警报的组件）。</li></ul></li><li><strong>Prometheus 配置</strong>： <ul><li>Prometheus使用YAML文件进行配置，包括Scrape配置、Service Discovery等。</li><li>Service Discovery支持静态配置、Kubernetes、文件SD等。</li><li>监控应具备弹性和可扩展性，可使用多个Prometheus实例进行水平扩展。</li></ul></li><li><strong>Prometheus 查询语言 (PromQL)</strong>： <ul><li>PromQL是Prometheus的查询语言，支持瞬时向量、范围向量等类型。</li><li>示例查询包括计算文件系统使用率、计算指标每秒速率、联合不同Exporter的指标等。</li></ul></li><li><strong>Prometheus 警报</strong>： <ul><li>Prometheus警报使用PromQL表达式，支持条件、持续时间、标签等。</li><li>Prometheus提供了默认的警报和仪表板，用户可以根据需求进行定制。</li></ul></li><li><strong>Ceph监控与Prometheus结合</strong>： <ul><li>Ceph的manager模块可以作为Exporter使用，暴露Ceph集群的指标。</li><li>Prometheus可以监控Ceph集群的各种指标，如存储使用率、性能、可用性等。</li><li>用户可以根据需要添加自定义警报和仪表板。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>推广Prometheus在Ceph集群中的应用。</li><li>提供Prometheus配置和查询语言的文档。</li><li>开发Ceph的Prometheus Exporter。</li><li>收集用户反馈，改进Prometheus功能。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议介绍了Prometheus监控工具及其在Ceph集群中的应用。Prometheus具有强大的功能和易用性，是Ceph集群监控的理想选择。</p>",10)])])}const g=t(s,[["render",l]]);export{m as __pageData,g as default};
